from pathlib import Path
import json,re,html,subprocess,os
S=Path(__file__).resolve().parent;R=S.parent;root=Path.cwd()
a=json.loads((S/'results.json').read_text())
def f(v,d=1):return f'{v:,.{d}f}'
def pct(v):return f'{100*v:.1f}%'
def table(headers,rows):return '<table class="bridge"><thead><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def chart(name):return '<figure class="fig">'+(S/'charts'/f'{name}.svg').read_text()+'</figure>'
best=a['selection']['best'];test=next(x for x in a['model_metrics'] if x['model']==best and x['split'].startswith('Test')); lag=next(x for x in a['model_metrics'] if x['model']=='Last week' and x['split'].startswith('Test'))
specs=[{'id':'hour','form':'line','title':'Rentals peak at 18:00 overall','subtitle':'Mean rentals per functioning hour; all seasons','x':[str(x['dimension']).zfill(2) for x in a['hour']],'series':[{'name':'Hourly rentals','values':[x['mean'] for x in a['hour']]}],'value_format':'{:,.0f}'},
{'id':'errors','form':'hbar','title':'Recent matching hours beat last week','subtitle':'September–November hourly MAE; lower is better','rows':[{'label':x['model'].replace('hour/daytype','matching hour'),'value':x['mae']} for x in a['model_metrics'] if x['split'].startswith('Test')],'value_format':'{:,.0f}'},
{'id':'forecast','form':'line','title':'Next-day example: midday and afternoon lead','subtitle':'1 December 2018; assumes scheduled operation, calendar only','x':[str(x['h']).zfill(2) for x in a['next_day']],'series':[{'name':'Predicted rentals','values':[x['forecast'] for x in a['next_day']]}],'value_format':'{:,.0f}'}]
(S/'chart_specs.json').write_text(json.dumps(specs,indent=2))
subprocess.run(['uv','run','.claude/skills/dataviz/scripts/render.py',str(S/'chart_specs.json'),'--out-dir',str(S/'charts'),'--single-mode','light'],check=True)
subprocess.run(['uv','run','.claude/skills/dataviz/scripts/validate_palette.py','#2a78d6','--mode','light'],check=True,stdout=(S/'palette.txt').open('w'))
body='''<main class="page"><div class="kicker">Seoul Bike Sharing · demand planning</div><h1>Plan around seasonal peaks; keep weather-sensitive capacity flexible</h1><div class="byline">Supplied hourly data: 1 December 2017–30 November 2018 · Prepared 4 November 2026 · bmalthi</div>'''
body+=f'''<section class="bottomline"><p>Prioritize the evening commute in spring–autumn and the morning commute in winter. A calendar-only daily forecast cuts held-out hourly error by <b>{pct(1-test['mae']/lag['mae'])}</b> against last week, but rainy hours remain poorly forecast. Use it for a monitored scheduling pilot; station-level bike availability and truck staffing cannot be sized from these network rental counts alone.</p></section>'''
body+='''<h2>Evening demand dominates, but winter changes the schedule</h2><p>The file contains <b>6,172,314 rentals</b> across 8,760 hours. Of these, 295 hours are marked non-functioning and record zero rentals; they are service closures, not evidence of zero latent demand. Profiles below use the 8,465 functioning hours.</p>'''+chart('hour')
body+=table(['Hour','Operating hours','Mean rentals','Historical p90'],[[f"{x['dimension']:02}:00",x['hour_count'],f(x['mean']),f(x['p90'])] for x in a['hour']])
body+='<p>Summer averages '+f(next(x['mean'] for x in a['season'] if x['dimension']=='Summer'))+' rentals per operating hour, versus '+f(next(x['mean'] for x in a['season'] if x['dimension']=='Winter'))+' in winter. These are historical associations, not effects of season alone.</p>'
body+=table(['Season','Operating hours','Mean rentals/hour','Historical p90'],[[x['dimension'],x['hour_count'],f(x['mean']),f(x['p90'])] for x in a['season']])
body+='<p><b>The operational flip test:</b> a universal evening staffing rule fails in winter. Workdays peak at 18:00 in the other seasons but at 08:00 in winter. Off days (weekends or holidays) have a later, flatter leisure profile; their seasonal peak hour also varies.</p>'
body+=table(['Season','Day type','Peak hour','Mean at peak','Observed peak hours'],[[x['season'],x['daytype'],f"{x['h']:02}:00",f(x['mean']),x['n']] for x in a['season_peak']])
body+='''<h2>Rain is the largest forecast warning; holidays are partly a mix effect</h2><p>At comparable season × hour × work/off-day cells with at least three wet and three dry observations, rainy hours average <b>169 rentals</b> versus <b>871</b> for dry hours weighted to the rainy-hour mix (418 rainy observations, 83 cells). This remains observational: rain severity, temperature and unmeasured availability differ. It supports a weather alert, not an 81% causal adjustment.</p>'''
for key,label in [('temperature','Temperature'),('rain','Rainfall'),('snow','Snowfall'),('humidity','Humidity'),('wind','Wind speed')]:
 body+='<h3>'+label+'</h3>'+table(['Condition','Operating hours','Mean rentals/hour'],[[x['dimension'],x['n'],f(x['mean'])] for x in a[key]])
body+=table(['Calendar category','Operating hours','Mean rentals/hour'],[[x['dimension'],x['hour_count'],f(x['mean'])] for x in a['holiday']])
h=a['holiday_standardized'][0]
body+=f'''<p>Restricting to common season/hour cells with at least three holiday observations reduces the comparison to {h['holiday_n']} holiday hours: {f(h['holiday'])} rentals/hour versus {f(h['matched_normal'])} on non-holidays standardized to that season/hour mix. Weekday composition and weather still differ. Do not apply the raw holiday average as a universal discount.</p>'''
body+=table(['Functioning flag','Hours','Rentals'],[['Yes' if x['dimension'] else 'No',x['hour_count'],f(x['rentals'],0)] for x in a['functioning']])
body+='''<h2>A simple forecast wins an honest chronological comparison</h2><p><b>Daily rule:</b> at midnight, predict each operating hour with the mean rental count at the same clock hour and same work/off-day type over the preceding 28 calendar days, excluding closed hours. Never use the target day’s actual rentals or observed weather. This is a rolling local-average model, updated daily; it is not a single three-month-ahead forecast.</p><p>Select the window by June–August mean absolute error (MAE), then evaluate the locked choice in September–November. Earlier December–May history is available for initialization. Both validation and final test favor 28 days. The comparison uses exactly the same operating hours for all models; last-week forecasts fall back to the 28-day rule when the prior week’s hour was closed.</p>'''+chart('errors')
body+=table(['Model','Validation MAE','Test MAE','Test RMSE','Test WAPE'],[[x['model'],f(next(v['mae'] for v in a['model_metrics'] if v['model']==x['model'] and v['split'].startswith('Validation'))),f(x['mae']),f(x['rmse']),pct(x['wape'])] for x in a['model_metrics'] if x['split'].startswith('Test')])
body+=f'''<p>Final test: {test['n']:,} operating hours, <b>{f(test['mae'])} rentals/hour MAE</b>, {pct(test['wape'])} weighted absolute percentage error, and {pct(test['bias'])} aggregate overprediction. WAPE is total absolute error divided by total observed rentals; it is not an average percentage error per hour.</p>'''
body+=table(['Month','Operating hours','MAE','WAPE','Forecast bias'],[[x['period'],x['n'],f(x['mae']),pct(x['wape']),pct(x['bias'])] for x in a['selected_months']])
body+='<p>Rain exposes the limitation of calendar-only predictions. Retrospective weather slicing is diagnostic, not a deployment input:</p>'+table(['Final-test weather','Hours','MAE','WAPE'],[[x['weather'],x['n'],f(x['mae']),pct(x['wape'])] for x in a['selected_rain']])
body+='''<h3>What is actually available before the day starts?</h3>'''+table(['Input','Deployment status'],[['Clock hour, date, weekend','Known in advance.'],['Holiday calendar','Known if supplied by the operator; classification assumes the published schedule is available.'],['Previous rentals and operation flags','Known only after daily data arrives; refresh must fail closed when feeds are late.'],['Target functioning status','Use a planned closure schedule, not the future observed flag. Reported main errors exclude closures; all-hour gated scores assume the schedule was known.'],['Temperature, rain, snow, wind, humidity, solar, visibility, dew point','The supplied values are realized observations. They are excluded from the forecast. A weather-enhanced model needs archived, timestamped forecasts and a new chronological backtest.']])
body+='''<h2>A planning envelope is useful, but it is not a fleet guarantee</h2><p>The preceding 28-day matching-hour 90th percentile covers only <b>83.5%</b> of validation hours and <b>87.9%</b> of final-test hours. Calling it a “90% service level” would be misleading.</p>'''
buf=a['service_buffer'];ce=a['calibrated_envelope'][0]
body+=f'''<p>Add <b>{f(buf,2)} rentals/hour</b>, the validation-only 90th percentile of actual-minus-historical-p90. Freeze that correction before the final test. The resulting upper planning envelope covers <b>{pct(ce['coverage'])}</b> of September–November operating hours ({pct(a['calibrated_by_daytype'][0]['coverage'])} workdays; {pct(a['calibrated_by_daytype'][1]['coverage'])} off days). It leaves an average {f(ce['slack'])} rentals/hour of headroom and {f(ce['unmet_proxy'])} rentals/hour above the envelope, averaged across all test hours.</p><p>Those are volume-proxy tradeoffs, <b>not actual idle bikes or unmet trips</b>. The correction has no statistical guarantee under seasonal drift; test rows are serially dependent and the holdout covers autumn only. It is a starting point for a service-planning pilot, not a staffing or stock procurement target.</p>'''
body+='''<h2>The model produces a full next-day planning curve</h2><p>Illustration at the dataset boundary: <b>1 December 2018</b>, treated as an off day with scheduled operation. No actual outcomes for that day are used or supplied. Each hour has seven matching operating observations in the preceding 28 days. Transition into winter may invalidate this November-based curve; it must be reviewed against recent bias and weather forecasts before use.</p>'''+chart('forecast')
body+=table(['Hour','Point forecast','Planning envelope'],[[f"{x['h']:02}:00",f(x['forecast']),f(x['historical_p90']+buf)] for x in a['next_day']])
body+='''<section class="rec"><h2>Recommendation</h2><p><b>Pilot daily capacity scheduling with a seasonal override.</b> Stage rebalancing before the 18:00 workday peak in spring–autumn, and before 08:00 in winter. On off days, follow the local afternoon/evening curve rather than copying commute shifts. Reserve 01:00–05:00 as a candidate maintenance window: its historical mean is 249 rentals/hour versus 1,207 during 16:00–20:00; keep a service floor because demand remains nonzero.</p><p><b>Keep rain-day staffing flexible.</b> Review next-day forecast alerts and use cancellable/redeployable capacity; do not automate a weather discount from realized-weather associations. Pair the forecast with the operator’s planned closure calendar and reopen with a conservative manual plan when recent matching history is sparse.</p><p><b>Size trucks and bikes only after adding station flows.</b> Obtain origin/destination trips, journey duration, station inventory, empty/full events, unsuccessful rental attempts, maintenance availability and truck turnaround. Then simulate inventory paths and test station-level service targets. Network rentals per hour cannot determine required bikes, staff counts or which station needs a truck.</p></section>'''
body+='''<h2>Watch items and drift controls</h2><ul><li><b>Forecast failure:</b> monitor rolling weekly MAE/WAPE and signed error by hour, day type, weather alert and season. Compare with the last-week baseline at the same timestamps. Investigate persistent signed bias or a model that no longer beats baseline; the November holdout already overpredicts by 18.3%.</li><li><b>Service envelope:</b> track actual coverage and headroom by hour and day type. If coverage falls below the intended operating target, recalibrate from a recent completed window and retest before changing capacity. The current correction is not validated through a fresh winter.</li><li><b>Data and closure drift:</b> alert on missing/duplicate hours, late feeds, changed unit definitions, and scheduled-versus-actual closure mismatches. Never train closed-hour zeros into the operating-demand baseline.</li><li><b>Suppressed demand:</b> low rentals may mean empty docks or poor availability, not weak demand. Add stockouts and failed attempts before reducing supply based on the forecast.</li><li><b>Structural change:</b> one year cannot identify multi-year growth, network expansion or recurring seasonality separately. New stations, fares or mobility patterns require a fresh backtest. The supplied historical exercise does not describe current Seoul operations.</li></ul>'''
body+='''<h2>Methodology</h2><div class="method"><p>Read-only source: supplied <code>seoul-bike-sharing-demand-local/data.csv</code>. Dates parsed explicitly as day/month/year. SOURCE.txt attributes the dataset to UCI Seoul Bike Sharing Demand, DOI 10.24432/C5F62R, CC BY 4.0; the exercise is a local adaptation, not a verified company take-home. No external data or realized future outcomes were used.</p><p>Quality: 365 complete calendar days, no duplicate date/hour keys, no missing modeled or diagnostic fields, no negative rentals or invalid hours. All 295 non-functioning hours have zero rentals. The total 6,172,314 rentals independently reconciles through season/hour groups; holdout MAE and WAPE independently reconcile from hourly error aggregates. Raw hours stay inside an in-memory DuckDB session; saved SQL and JSON contain calculations and aggregate outputs only.</p><p>Reproduce from the repository root with <code>uv run examples/seoul-bike-sharing-demand/workspace/scratch/analyze.py</code>, then <code>supplement.py</code> and <code>build_brief.py</code> from the same scratch directory. Full commands, metric definitions, instruments and assumptions are in methodology.md. Charts use inline SVG and all plotted values appear in adjacent tables.</p></div>'''
body+='''<h2>Question &amp; Framing</h2><div class="method"><p><b>As asked:</b> advise a city bike-share operator on fleet availability; diagnose demand by hour, season, weather, holiday and functioning status; build a forecast or decision model with deployment-known predictors; recommend service-level, staffing or rebalancing actions; explain misleading-model risks and drift monitoring.</p>'''+table(['Framing decision','Resolved as'],[['Population','All supplied network hourly counts; operating-demand analyses exclude non-functioning hours, which are separately reported.'],['Forecast','One day ahead, refreshed at midnight from earlier days. Mean of recent matching operating hours; no realized target weather.'],['Validation','June–August 2018 model selection; September–November 2018 final walk-forward evaluation.'],['Decision','A scheduling pilot and network volume envelope; station inventory and causal interventions remain unidentified.'],['Deliverable','Self-contained report with full forecast, diagnostics, operational metrics and reproducible aggregate SQL.'],['User steer','Use supplied data, not look up what actually happened.']])+'''</div><div class="foot">Local homework analysis · Historical observed rentals, not unconstrained demand · bmalthi</div></main>'''
template=(root/'.claude/skills/analyse/assets/brief_template.html').read_text()
template=re.sub(r'<!--.*?-->','',template,flags=re.S)
template=re.sub(r'<title>.*?</title>','<title>Seoul bike demand — planning brief</title>',template,flags=re.S)
template=re.sub(r'<body>.*?</body>','<body>'+body+'</body>',template,flags=re.S)
(R/'brief.html').write_text(template)
print('wrote',R/'brief.html')
